import{_ as o,C as t,o as c,c as d,E as a,a2 as l}from"./chunks/framework.DeifPYC6.js";const _=JSON.parse('{"title":"计划确认何时失效，执行时又检查什么？","description":"","frontmatter":{"title":"计划确认何时失效，执行时又检查什么？","date":"2026-10-22","column":"industry-architecture","category":"daily","article_type":"comparative-study","edition":"research-center","research_question":"计划确认的新鲜度与执行请求权限如何分别检查？（How should confirmation freshness and execution-request authority be checked separately?）","summary":"十二组辅助函数输入显示评论失效的默认值与例外；文档版本确认和调用权限仍需分别验证。","sources":"Paperclip pinned source; MuleSoft official policy documentation; 2026-10-22 internal helper probe","pageClass":"runtime-v6-article","item_id":"SIG-20261022-001","lifecycle":"Published","cover":"/assets/covers/daily-2026-10-22-sig-20261022-001-2026-10-22-plan-confirmation-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/industry/2026-10-22-plan-confirmation.md","filePath":"zh/industry/2026-10-22-plan-confirmation.md","lastUpdated":1792681615000}'),n={name:"zh/industry/2026-10-22-plan-confirmation.md"};function s(p,e,h,b,u,f){const r=t("ArticleCover"),i=t("ArticleTableScroll");return c(),d("div",null,[a(r,{image:"/assets/covers/daily-2026-10-22-sig-20261022-001-2026-10-22-plan-confirmation-cover.png",kicker:"研究成果",title:"计划确认何时失效，执行时又检查什么？",summary:"十二组辅助函数输入显示评论失效的默认值与例外；文档版本确认和调用权限仍需分别验证。",version:"2026-10-22",languageHref:"/en/industry/2026-10-22-plan-confirmation",languageLabel:"English"}),a(i,{language:"zh"}),e[0]||(e[0]=l('<h1 id="计划确认何时失效-执行时又检查什么" tabindex="-1">计划确认何时失效，执行时又检查什么？ <a class="header-anchor" href="#计划确认何时失效-执行时又检查什么" aria-label="Permalink to &quot;计划确认何时失效，执行时又检查什么？&quot;">​</a></h1><p>在问题讨论串里补充一句意见，待确认的计划会自动作废吗？本次内部探针给出的答案取决于配置和交互类型。这对连接人工确认与智能体执行的平台架构师很关键：先查清确认针对哪个版本、何时失效，再另查执行请求是否获准，才能知道证据链还缺哪一段。</p><h2 id="一条评论-并非统一撤销指令" tabindex="-1">一条评论，并非统一撤销指令 <a class="header-anchor" href="#一条评论-并非统一撤销指令" aria-label="Permalink to &quot;一条评论，并非统一撤销指令&quot;">​</a></h2><p>Paperclip（智能体组织协作平台）的指南区分正式审批与普通讨论串确认：招聘、战略以及涉及支出或安全的动作有正式审批路径；计划讨论可使用普通确认交互。指南建议将计划确认绑定到最新计划修订，使用基于修订的防重复键，显式启用评论触发失效，并在接受后再建立实施子任务。<a href="https://github.com/paperclipai/paperclip/blob/ba9e6e4bc5b327e19b95bd2d6ea8f09609170cf1/docs/guides/agent-developer/handling-approvals.md" target="_blank" rel="noreferrer">处理审批指南</a></p><p>同日分析阶段抽出固定源码中的输入规范化与评论替代判断两个原始辅助函数，去除类型标注后执行 12 组人工输入，结果全部符合预设。以下是关键分支，而不是完整事件路径的测试：</p><table tabindex="0"><thead><tr><th>确认类型</th><th>未配置或显式关闭</th><th>显式开启评论失效</th></tr></thead><tbody><tr><td>普通计划确认</td><td>不由该辅助规则触发</td><td>由该辅助规则触发</td></tr><tr><td>绑定工具动作的确认</td><td>不触发</td><td>仍不触发</td></tr><tr><td>连接意图交互</td><td>不触发</td><td>仍不触发</td></tr></tbody></table><p>来源：2026-10-22 内部隔离探针，固定 <a href="https://github.com/paperclipai/paperclip/blob/ba9e6e4bc5b327e19b95bd2d6ea8f09609170cf1/server/src/services/issue-thread-interactions.ts" target="_blank" rel="noreferrer">ba9e6e4 版本交互服务</a>。另用提问交互作为可适用类型的控制。工具动作是人工构造对象，只触发“存在该对象”的分支，并不代表通过完整结构校验的真实动作。</p><p>这与指南不矛盾：指南要求显式启用，代码默认关闭。默认值可以是产品选择，工具动作和连接意图也可能另有生命周期。辅助函数排除它们，不意味着这些路径没有其他保护，更不是已经复现了漏洞。此处讨论的是待处理确认能否被评论替代，不能直接推成“所有已接受审批都被撤销”。</p><h2 id="文档改版是另一条检查路径" tabindex="-1">文档改版是另一条检查路径 <a class="header-anchor" href="#文档改版是另一条检查路径" aria-label="Permalink to &quot;文档改版是另一条检查路径&quot;">​</a></h2><p>已读服务源码还比较当前文档修订身份及可选修订号，并考虑问题、公司和文档归属。目标已过期的路径会让绑定该目标的待处理交互到期，并保留旧目标信息。源码中的文档行加锁选项与对应测试定义，为这种实现路径提供了静态依据。<a href="https://github.com/paperclipai/paperclip/blob/ba9e6e4bc5b327e19b95bd2d6ea8f09609170cf1/server/src/services/issue-thread-interactions.ts" target="_blank" rel="noreferrer">目标版本检查源码</a>、<a href="https://github.com/paperclipai/paperclip/blob/ba9e6e4bc5b327e19b95bd2d6ea8f09609170cf1/server/src/__tests__/issue-thread-interactions-service.test.ts" target="_blank" rel="noreferrer">服务测试定义</a></p><p>要分清两件事：评论失效是有默认值和例外的规则；目标版本检查关心确认是否仍指向当前文档。存在测试定义也不等于本轮运行了数据库测试。本次没有执行评论分发、数据库更新、并发接受或文档修订事务，不能据此声称竞争条件已经被覆盖。</p><p>一个简短审查例子是：确认请求绑定第一版计划，而文档已经进入第二版。审核者应先检查待处理交互对旧目标的处置，再问执行动作的参数是否仍对应第一版。前一个问题有本次静态来源支持，后一个端到端绑定仍待验证。这是检查方法，不是对现有产品行为的新增承诺。</p><h2 id="调用权限回答的是另一道问题" tabindex="-1">调用权限回答的是另一道问题 <a class="header-anchor" href="#调用权限回答的是另一道问题" aria-label="Permalink to &quot;调用权限回答的是另一道问题&quot;">​</a></h2><p>MuleSoft（企业集成平台）的官方策略文档讨论的是已认证主体对具体协议请求的权限。它使用 MCP（模型上下文协议）与 ABAC（基于属性的访问控制）策略，并通过 Cedar（授权策略语言）规则描述主体、工具、资源和提示相关的访问条件。文档要求先运行另一个认证策略，主体可用属性取决于前置认证方式。<a href="https://docs.mulesoft.com/gateway/latest/policies-included-mcp-attribute-access-control" target="_blank" rel="noreferrer">属性访问控制策略</a></p><p>两家来源提供的是不同控制点的材料，不能互相代证：</p><table tabindex="0"><thead><tr><th>审查问题</th><th>计划确认材料</th><th>网关策略材料</th></tr></thead><tbody><tr><td>人确认了什么</td><td>文档目标与修订</td><td>不负责解释该计划的人工意图</td></tr><tr><td>何时需要重新检查</td><td>目标改版及配置的失效规则</td><td>当前认证主体、属性与请求规则</td></tr><tr><td>可以断言到哪里</td><td>已检查的辅助函数与静态版本路径</td><td>文档定义的请求授权合同</td></tr><tr><td>本次没有建立什么</td><td>完整并发接受及执行绑定</td><td>已部署网关的安全效果</td></tr></tbody></table><p>来源：上述公开指南、固定源码与官方策略文档；表中责任划分是研究解释，不是两种产品已集成的实测结果。认证确认“谁在请求”，授权还要检查“这个主体能否对这个目标执行这个动作”；一个计划确认标记不能替代后一个判断。</p><h2 id="连接两道检查-需要哪些材料" tabindex="-1">连接两道检查，需要哪些材料？ <a class="header-anchor" href="#连接两道检查-需要哪些材料" aria-label="Permalink to &quot;连接两道检查，需要哪些材料？&quot;">​</a></h2><p>我们建议平台团队把确认对象、版本、失效选项和例外记在一处，再沿执行路径寻找当前主体、实际动作参数、资源范围和策略决定。若声称某次人工接受约束了具体工具调用，应能展示两者的对应关系；若只展示按钮、认证结果或日志，就应把尚未检查的连接标为未知。</p><p>这不是要求把两个产品拼成某套架构，也不表示它们可直接互换。前述网关文档还有适用边界：不支持本地模式，页面声明支持 2025-06-18 及更早的协议版本。架构指南中的旧网关名称与当前链接文档的名称不同，本次只保留来源命名漂移，不将其写成已验证的发布事件。<a href="https://docs.mulesoft.com/gateway/latest/policies-included-mcp-attribute-access-control" target="_blank" rel="noreferrer">策略约束</a>、<a href="https://architect.salesforce.com/docs/architect/fundamentals/guide/mulesoft-architecting-agentic-enterprise" target="_blank" rel="noreferrer">企业架构指南</a></p><h2 id="证据边界留在具体路径上" tabindex="-1">证据边界留在具体路径上 <a class="header-anchor" href="#证据边界留在具体路径上" aria-label="Permalink to &quot;证据边界留在具体路径上&quot;">​</a></h2><p>公开一手事实在这里指指南和策略文档明示的规则；本次观察指对固定源码与测试定义的静态检查；内部实验依据只覆盖两个原辅助函数的 12 组输入，不是第三方安全验证。架构指南对安全、合规和可审计性的描述属于供应商陈述，本篇不采用它来证明安全效果。两家组织分别提供来源，不等于一家独立验证了另一家的机制。</p><p>Paperclip 材料固定于 <a href="https://github.com/paperclipai/paperclip/tree/ba9e6e4bc5b327e19b95bd2d6ea8f09609170cf1" target="_blank" rel="noreferrer">ba9e6e4 源码版本</a>；MuleSoft 材料为同日已读保存的官方架构及策略页面，没有在写作阶段重新抓取。源码和测试定义属于实现证据，文档属于合同证据；本次没有运行网关，也没有建立从人工确认到调用授权的完整绑定。发表、引用和评审状态都不能补齐这些缺口。</p><p>如果需要进一步确认，应单独研究修订更新与接受的并发顺序，以及身份、权限或参数变化后旧确认的处置。当前可支持的判断止于这里：确认的新鲜度与执行时的权限需要分别举证，连接本身也需要证据。</p>',24))])}const g=o(n,[["render",s]]);export{_ as __pageData,g as default};
